// Live fitting in the browser: the same Rust core as the CLI, compiled to wasm.
// Data slices are generated by scripts/make_docs_figures.py --bundle-slice, as real
// gzipped NIfTI-1 files; NiiVue reads and displays them directly (no reimplemented
// NIfTI parsing here). The only array handling this file owns is the flattening
// between a loaded NVImage's native voxel order and `fit_volume`'s C-order
// `[nx,ny,nz,nt]` contract (see crates/qmrust-wasm/src/api.rs), and a generic
// YAML-tree walk that turns a model's recipe into form widgets without ever
// naming a model or parameter.
import { Niivue, NVImage, DRAG_MODE } from "./vendor/niivue.js";
import { load as yamlLoad, dump as yamlDump } from "./vendor/js-yaml.js";
import { unzipSync, gunzipSync } from "./vendor/fflate.js";
import hljs from "./vendor/highlight-core.js";
import hljsYaml from "./vendor/highlight-yaml.js";
import * as echarts from "./vendor/echarts.js";

const $ = (id) => document.getElementById(id);
// The navbar status line. `kind` colours and weights it, because the two states
// a reader actually watches for — work in progress, and done — should be
// distinguishable at a glance rather than uniform grey.
//   "ok"    finished and usable      (green)
//   "busy"  something is happening   (rust)
//   "error" it did not work          (red)
//   "info"  neutral aside            (muted)
// A boolean is accepted for `kind` and means "error".
const status = (m, kind = "info") => {
  const el = $("status");
  el.textContent = m;
  const resolved = kind === true ? "error" : kind || "info";
  el.classList.remove("ok", "busy", "error");
  if (resolved !== "info") el.classList.add(resolved);
};

// Colormap per output unit, never per model/output name — mirrors
// scripts/docsfig/style.py's CMAP_BY_UNIT so the playground and the static
// figures agree. Only used as a *default*; the dropdown lets a reader
// override it with any colormap the vendored build actually ships.
const CMAP_BY_UNIT = { s: "magma", "1/s": "viridis", "%": "cividis", "": "inferno" };
const CANDIDATE_COLORMAPS = ["gray", "viridis", "magma", "inferno", "plasma", "hot", "cool", "turbo", "cividis"];

let wasm = null;
const bundleCache = {};
let current = null; // { meta, volume (NVImage), maskU8 (Uint8Array|null), frame }
// The fetched BIDS dataset behind `current`, when there is one:
// { archive, files: Map<path, Uint8Array>, resolved: ResolvedCollection }.
// `null` while the pre-baked demo slice is showing.
let dataset = null;
// True while a dataset is being fetched/extracted/resolved, so the tab switcher
// leaves the skeletons in place instead of revealing a half-built view.
let loading = false;
// A reader's own dropped dataset, waiting for the next `loadModel` to consume
// instead of fetching. Cleared once taken, so switching models afterwards goes
// back to the hosted datasets.
let droppedFiles = null;
// Every model the payload index lists, for asking which of them can fit a
// dropped dataset.
let modelNames = [];
let lastMaps = null; // { [outputName]: Float64Array }, C-order [nx,ny,nz] — every
// entry fit_volume returns, i.e. the model's full output_names(), not just the
// quantitative maps in meta.outputs.
let outputVolumes = []; // [{ name, unit, volume, defaultCalMin, defaultCalMax }]
let shownOutput = null; // the outputVolumes entry currently drawn in the fitted-map viewer
let availableColormaps = [];
// Config keys restricted to a fixed set of values (dotted path -> allowed
// values), from this model's bundle `enums` — the catalog/registry decides
// which keys get a dropdown, never a name or key hard-coded here.
let enumFields = new Map();
// Accumulated wheel `deltaY` for the inputs viewer's frame-step gesture (see
// the `wheel` listener in `main`); reset on every model load so a gesture
// mid-flight on the old model can't carry a partial step into the new one.
let wheelAccum = 0;
const WHEEL_STEP_THRESHOLD = 100;

// Recipe editor state: `text` is always the source of truth handed to
// fit_volume; `obj` is its parsed form (null while the text is invalid).
const editor = { text: "", obj: null, valid: false };

// The inputs viewer shows an acquired image, so linear interpolation (the
// default) is the right look. The fitted-map viewer shows per-voxel
// quantitative values with hard NaN boundaries at the mask edge; blending
// those linearly with neighboring voxels invents in-between colours at the
// boundary that were never fitted, so it uses nearest-neighbour instead —
// every displayed pixel is then one real fitted value.
// `loadingText` is what NiiVue draws on an empty canvas (0 volumes) — blanked
// here since both viewers only ever go empty transiently (before the first
// volume/fit loads), not in a state a reader should read as "something is
// loading".
const nvIn = new Niivue({ isResizeCanvas: true, backColor: [0.02, 0.02, 0.03, 1], loadingText: "" });
const nvOut = new Niivue({
  isResizeCanvas: true,
  backColor: [0.02, 0.02, 0.03, 1],
  isNearestInterpolation: true,
  loadingText: "",
});

async function loadWasm() {
  try {
    const mod = await import("./pkg/qmrust_wasm.js");
    await mod.default();
    return mod;
  } catch (e) {
    $("fallback").hidden = false;
    status("Fitting unavailable — wasm failed to load; viewers still work", "error");
    return null;
  }
}

async function fetchOrThrow(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: ${r.status}`);
  return r;
}

async function loadBundle(name) {
  if (bundleCache[name]) return bundleCache[name];
  const meta = await (await fetchOrThrow(`./data/${name}.json`)).json();
  bundleCache[name] = meta;
  return meta;
}

// ---------------------------------------------------------------------------
// Full BIDS datasets: fetched, unzipped, and resolved in the browser through
// the same `rust-bids` code the CLI's `--bids-dir` path runs. The acquisition
// comes from the dataset's own JSON sidecars, so the recipe for this path
// carries options only — see `meta.config_bids`.

let sourcesCache = null;
const datasetCache = {};

// The download ring, on the fitted-map skeleton — the one panel with nothing
// else to say while bytes arrive. `fraction` is null when the server sent no
// `Content-Length`, in which case the ring stays hidden rather than animating a
// number it cannot know.
const RING_CIRCUMFERENCE = 2 * Math.PI * 36; // r=36, matching the SVG

function setDownloadProgress(fraction) {
  const box = $("navbar-dl");
  if (fraction === null) {
    box.hidden = true;
    return;
  }
  box.hidden = false;
  const clamped = Math.max(0, Math.min(1, fraction));
  $("dl-arc").style.strokeDashoffset = String(RING_CIRCUMFERENCE * (1 - clamped));
  $("dl-pct").textContent = `${Math.round(clamped * 100)}%`;
}

function hideDownloadProgress() {
  setDownloadProgress(null);
}

// Read the body as a stream so progress is real rather than simulated. A
// server that sends no length (or a browser without streams) still works — it
// just gets no ring.
async function fetchWithProgress(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`fetch ${url} failed (HTTP ${res.status})`);
  const total = Number(res.headers.get("content-length")) || 0;
  if (!res.body?.getReader || !total) {
    return new Uint8Array(await res.arrayBuffer());
  }
  const reader = res.body.getReader();
  const chunks = [];
  let received = 0;
  setDownloadProgress(0);
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    received += value.length;
    setDownloadProgress(received / total);
  }
  const out = new Uint8Array(received);
  let at = 0;
  for (const c of chunks) {
    out.set(c, at);
    at += c.length;
  }
  return out;
}

// One loading stage, reported in both places a reader might be looking: the
// navbar status and whichever skeleton is on screen.
function stage(message) {
  status(message, "busy");
  // The files panel's own header doubles as the loading caption; the viewers
  // carry no text, only their shimmer.
  if (loading) $("files-summary").textContent = message;
}

// Compact number for a label: drops trailing zeros so 0.35 reads as 0.35 and
// 90.0 as 90.
const fmt = (v) => (typeof v === "number" ? String(Number(v.toPrecision(6))) : String(v));

async function loadSources() {
  if (!sourcesCache) {
    sourcesCache = await (await fetchOrThrow("./data/sources.json")).json();
  }
  return sourcesCache;
}

// Unzip into the dataset-root-relative `path -> bytes` shape `resolve_bids`
// requires. The archives wrap their dataset in a `ds-<slug>/` directory; that
// wrapper is the caller's to strip, since only the caller knows where its root
// is (a dropped folder answers differently).
function unzipDataset(buf) {
  const files = new Map();
  for (const [path, bytes] of Object.entries(unzipSync(buf))) {
    if (path.endsWith("/") || bytes.length === 0) continue;
    const cut = path.indexOf("/");
    files.set(cut === -1 ? path : path.slice(cut + 1), bytes);
  }
  return files;
}

// A volume's label, from whatever identity it resolved to — a role name for a
// named measurement, its parameter values for a series one. Never keyed on a
// model or parameter name.
function identityLabel(id) {
  if (!id) return "volume";
  if (id.role) return id.role;
  const parts = Object.entries(id.params ?? {}).map(([k, v]) => `${k}=${fmt(v)}`);
  return parts.length ? parts.join(", ") : "volume";
}

async function fetchDataset(name, meta) {
  // A dataset the reader dropped takes precedence over the hosted one, and is
  // consumed once: from here on it is indistinguishable from a fetched dataset.
  if (droppedFiles) {
    const files = droppedFiles;
    droppedFiles = null;
    stage(`Resolving ${files.size} files as BIDS…`);
    return {
      archive: "your dataset",
      files,
      collections: wasm.resolve_bids(files, meta.config_bids, ""),
    };
  }
  if (datasetCache[name]) return datasetCache[name];
  const src = await loadSources();
  const url = `${src.base}/${meta.archive}${src.suffix}`;
  stage("Downloading example data…");
  const buf = await fetchWithProgress(url);

  stage(`Extracting ${(buf.length / 1e6).toFixed(1)} MB…`);
  let files;
  try {
    files = unzipDataset(buf);
  } catch (e) {
    throw new Error(`could not read ${meta.archive} (${buf.length} bytes): ${e.message}`);
  }

  stage(`resolving ${files.size} files as BIDS…`);
  const collections = wasm.resolve_bids(files, meta.config_bids, "");
  const dataset = { archive: meta.archive, files, collections };
  datasetCache[name] = dataset;
  return dataset;
}

// ---------------------------------------------------------------------------
// Recipe editor: a generic walk over the parsed YAML tree. Nothing here
// branches on a model, parameter, or key name — every widget kind is chosen
// purely from the JS type of the value found at that path.

function getAtPath(root, path) {
  let node = root;
  for (const k of path) node = node?.[k];
  return node;
}

function setAtPath(root, path, value) {
  let node = root;
  for (const k of path.slice(0, -1)) node = node[k];
  node[path.at(-1)] = value;
}

function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

function isNumberArray(v) {
  return Array.isArray(v) && v.every((x) => typeof x === "number");
}

// A matrix: an array of same-shaped number arrays (e.g. a protocol table of
// [angle, offset] rows). Generic on shape alone, like every other widget
// here — never on a key name.
function isNumberMatrix(v) {
  return (
    Array.isArray(v) &&
    v.length > 0 &&
    v.every((row) => isNumberArray(row) && row.length === v[0].length)
  );
}

// Re-derives `editor.text` from `editor.obj` after a form edit, and refreshes
// the (possibly hidden) YAML textarea + status pill to match.
function commitObjEdit() {
  editor.text = yamlDump(editor.obj);
  editor.valid = true;
  $("cfg-yaml").value = editor.text;
  setYamlPill(true);
}

function fieldRow(label, path, widget) {
  const row = document.createElement("div");
  row.className = "field-row";
  const labelWrap = document.createElement("div");
  const labelSpan = document.createElement("span");
  labelSpan.className = "field-label";
  labelSpan.textContent = label.replace(/_/g, " ");
  const keySpan = document.createElement("span");
  keySpan.className = "field-key";
  keySpan.textContent = path.join(".");
  labelWrap.append(labelSpan, keySpan);
  row.append(labelWrap, widget);
  return row;
}

function buildWidget(value, path) {
  const enumValues = enumFields.get(path.join("."));
  if (enumValues && typeof value === "string") {
    const select = document.createElement("select");
    for (const opt of enumValues) {
      const o = document.createElement("option");
      o.value = opt;
      o.textContent = opt;
      select.append(o);
    }
    select.value = value;
    select.onchange = () => {
      setAtPath(editor.obj, path, select.value);
      commitObjEdit();
    };
    return select;
  }
  if (typeof value === "boolean") {
    const label = document.createElement("label");
    label.className = "switch";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = value;
    input.onchange = () => {
      setAtPath(editor.obj, path, input.checked);
      commitObjEdit();
    };
    const slider = document.createElement("span");
    slider.className = "slider";
    label.append(input, slider);
    return label;
  }
  if (typeof value === "number") {
    const input = document.createElement("input");
    input.type = "number";
    input.step = "any";
    input.value = String(value);
    input.onchange = () => {
      const v = Number(input.value);
      setAtPath(editor.obj, path, Number.isFinite(v) ? v : value);
      commitObjEdit();
    };
    return input;
  }
  if (isNumberArray(value)) {
    const input = document.createElement("input");
    input.type = "text";
    input.value = value.join(", ");
    input.onchange = () => {
      const parsed = input.value
        .split(",")
        .map((s) => Number(s.trim()))
        .filter((n) => !Number.isNaN(n));
      setAtPath(editor.obj, path, parsed);
      commitObjEdit();
    };
    return input;
  }
  if (typeof value === "string") {
    const input = document.createElement("input");
    input.type = "text";
    input.value = value;
    input.onchange = () => {
      setAtPath(editor.obj, path, input.value);
      commitObjEdit();
    };
    return input;
  }
  if (isNumberMatrix(value)) {
    // One row per line ("a, b, c"), the same compact notation the plain
    // number-array widget above uses — far more readable than the nested
    // block-YAML (`- - a\n  - b`) the generic fallback below would otherwise
    // produce for an array of arrays.
    const ta = document.createElement("textarea");
    ta.value = value.map((row) => row.join(", ")).join("\n");
    ta.onchange = () => {
      const rows = ta.value
        .split("\n")
        .map((line) => line.trim())
        .filter((line) => line.length > 0)
        .map((line) => line.split(",").map((s) => Number(s.trim())));
      if (rows.every((row) => row.every((n) => Number.isFinite(n)))) {
        setAtPath(editor.obj, path, rows);
        commitObjEdit();
      }
    };
    return ta;
  }
  // Fallback for shapes a compact widget can't represent (array of arrays of
  // differing lengths, array of objects, null): a small YAML textarea for
  // just that subtree.
  const ta = document.createElement("textarea");
  ta.value = value == null ? "" : yamlDump(value).trimEnd();
  ta.onchange = () => {
    try {
      const parsed = ta.value.trim() === "" ? null : yamlLoad(ta.value);
      setAtPath(editor.obj, path, parsed);
      commitObjEdit();
    } catch (e) {
      // Leave the underlying object untouched; the textarea keeps the
      // reader's (currently unparsable) text so they can keep fixing it.
    }
  };
  return ta;
}

function buildGroup(container, entries, path) {
  for (const [key, value] of entries) {
    // `model` at the config root is the reserved key that selects the model
    // itself — part of the config format, not a per-model field — and the
    // model dropdown above the recipe editor already owns it, so a form row
    // for it here would just be a redundant, editable duplicate.
    if (path.length === 0 && key === "model") continue;
    const childPath = [...path, key];
    if (isPlainObject(value)) {
      const group = document.createElement("div");
      group.className = "group";
      const title = document.createElement("div");
      title.className = "group-title";
      title.textContent = key;
      const fields = document.createElement("div");
      fields.className = "form-fields";
      group.append(title, fields);
      buildGroup(fields, Object.entries(value), childPath);
      container.append(group);
    } else {
      container.append(fieldRow(key, childPath, buildWidget(value, childPath)));
    }
  }
}

function renderForm() {
  const container = $("form-fields");
  container.replaceChildren();
  if (!editor.obj || typeof editor.obj !== "object") return;
  buildGroup(container, Object.entries(editor.obj), []);
}

function setYamlPill(valid) {
  const pill = $("yaml-pill");
  pill.textContent = valid ? "valid" : "invalid";
  pill.classList.toggle("valid", valid);
  pill.classList.toggle("invalid", !valid);
}

// Sets the editor from a fresh string (model load, or typed into the YAML
// view). Rebuilds the form only when the text parses, so a reader mid-typo
// in the YAML view doesn't have the form yanked out from under them.
function setEditorText(text) {
  editor.text = text;
  $("cfg-yaml").value = text;
  paintYaml();
  try {
    editor.obj = yamlLoad(text);
    editor.valid = true;
    setYamlPill(true);
    renderForm();
  } catch (e) {
    editor.valid = false;
    setYamlPill(false);
  }
}

// ---------------------------------------------------------------------------
// YAML highlighting, by highlight.js (vendored). A highlighted <pre> sits behind
// a transparent-text textarea, the two sharing identical metrics and scroll
// offset so the painted tokens line up under the real caret. The textarea stays
// the single source of truth for text and editing, and `js-yaml` remains the
// only thing that parses meaning — the `valid`/`invalid` pill comes from it.

hljs.registerLanguage("yaml", hljsYaml);

// Repaint the layer behind the textarea and keep the two scrolled together.
function paintYaml() {
  const ta = $("cfg-yaml");
  // A trailing newline would collapse in the <pre>, shifting the last line.
  $("yaml-hl").innerHTML = `${hljs.highlight(ta.value, { language: "yaml" }).value}\n`;
  syncYamlScroll();
}

function syncYamlScroll() {
  const ta = $("cfg-yaml");
  const hl = $("yaml-hl");
  hl.scrollTop = ta.scrollTop;
  hl.scrollLeft = ta.scrollLeft;
}

function showTab(tab) {
  const isForm = tab === "form";
  $("tab-form").classList.toggle("active", isForm);
  $("tab-yaml").classList.toggle("active", !isForm);
  $("tab-form").setAttribute("aria-selected", String(isForm));
  $("tab-yaml").setAttribute("aria-selected", String(!isForm));
  $("form-view").hidden = !isForm;
  $("yaml-view").hidden = isForm;
  if (isForm && editor.valid) renderForm();
}

// ---------------------------------------------------------------------------

// Every element of `flat` (C-order `[nx,ny,nz]`, i.e. index `(x*ny+y)*nz+z`,
// matching fit_volume's own output convention) read from `volume` via its
// public accessor, so slope/intercept and orientation are handled exactly as
// NiiVue would for display — no separate raw-buffer indexing to get wrong.
// These bundles carry no qform/sform (a single downsampled slice has no
// meaningful scanner orientation), so NiiVue's own axis order is already
// native `dim[1]`/`dim[2]` order — the same order `fit_volume`, the output
// maps, and the `probes` oracle all use.
function readVolumeSeries(volume, nx, ny, nz, nt) {
  const flat = new Float64Array(nx * ny * nz * nt);
  for (let x = 0; x < nx; x++) {
    for (let y = 0; y < ny; y++) {
      for (let z = 0; z < nz; z++) {
        for (let t = 0; t < nt; t++) {
          flat[((x * ny + y) * nz + z) * nt + t] = volume.getValue(x, y, z, t);
        }
      }
    }
  }
  return flat;
}

// C-order `[nx,ny,nz]`, single frame — the same convention `readVolumeSeries`
// uses per timepoint, and the one `fit_volume`'s `mask`/`aux` arguments want.
function readScalarVolume(volume, nx, ny, nz) {
  const flat = new Float64Array(nx * ny * nz);
  for (let x = 0; x < nx; x++) {
    for (let y = 0; y < ny; y++) {
      for (let z = 0; z < nz; z++) {
        flat[(x * ny + y) * nz + z] = volume.getValue(x, y, z, 0);
      }
    }
  }
  return flat;
}

function readMask(volume, nx, ny, nz) {
  const raw = readScalarVolume(volume, nx, ny, nz);
  return Uint8Array.from(raw, (v) => (v > 0 ? 1 : 0));
}

// Fixed 2nd/98th-percentile window over the finite (in-mask, fitted) values —
// the same rule `scripts/docsfig/style.py`'s `window()` uses for the
// committed figures, so the browser and the published figures agree, and a
// few boundary-stuck fit failures (e.g. a grid search pinned at its T1 upper
// bound) cannot single-handedly drag the whole map's range out to them the
// way a plain min/max would.
function percentileWindow(values) {
  const finite = [];
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (Number.isFinite(v)) finite.push(v);
  }
  if (finite.length === 0) return [0, 1];
  finite.sort((a, b) => a - b);
  const at = (p) => {
    const idx = (p / 100) * (finite.length - 1);
    const lo = Math.floor(idx);
    const hi = Math.ceil(idx);
    return lo === hi ? finite[lo] : finite[lo] + (finite[hi] - finite[lo]) * (idx - lo);
  };
  const lo = at(2);
  const hi = at(98);
  return hi > lo ? [lo, hi] : [lo, lo + 1];
}

// Rounds a colour-scale bound to ~3 significant figures for display in the
// min/max inputs — full float precision is not a meaningful "default", and
// doesn't fit the input box either.
function roundBound(v) {
  if (!Number.isFinite(v) || v === 0) return 0;
  const digits = Math.max(0, 2 - Math.floor(Math.log10(Math.abs(v))));
  return Number(v.toFixed(Math.min(6, digits)));
}

// Build a displayable NVImage for one output map from `flat` (C-order
// `[nx,ny,nz]`, NaN outside the fit), reusing `template`'s header/orientation
// (NVImage.zerosLike) rather than hand-rolling a NIfTI header.
function buildMapVolume(template, flat, nx, ny, nz, name, unit, displayRange) {
  const vol = NVImage.zerosLike(template, "float32");
  vol.hdr.dims = template.hdr.dims.slice();
  vol.hdr.dims[0] = 3;
  vol.hdr.dims[4] = 1;
  vol.nFrame4D = 1;
  // The model's declared window for this quantity when it has one: a window
  // derived from the data is only as good as the data, and an unmasked fit puts
  // background noise in the same histogram as tissue. Falls back to a
  // percentile window for outputs whose scale genuinely belongs to the data
  // (an arbitrary-unit amplitude, say).
  const [lo, hi] = displayRange ?? percentileWindow(flat);
  // Unfitted voxels (NaN — outside the mask, or a failed fit) must not read
  // as the *brightest* colour in the map, which is what an unclamped NaN
  // texel does here. Park them well below the display window so they clamp
  // to the colormap's dark end instead — the GPU equivalent of
  // `docsfig.style`'s `cm.set_bad(BG)`.
  const sentinel = lo - Math.max(1, hi - lo);
  const img = new Float32Array(nx * ny * nz);
  for (let x = 0; x < nx; x++) {
    for (let y = 0; y < ny; y++) {
      for (let z = 0; z < nz; z++) {
        const v = flat[(x * ny + y) * nz + z];
        img[x + y * nx + z * nx * ny] = Number.isFinite(v) ? v : sentinel;
      }
    }
  }
  vol.img = img;
  vol.name = `${name}${unit ? ` [${unit}]` : ""}`;
  // Trust the percentile window computed above rather than have NiiVue
  // recompute its own min/max from the raw buffer — which would include the
  // dark-end sentinel just written in for NaN and pull the window back out
  // to it.
  vol.trustCalMinMax = true;
  // The colorbar is a custom HTML/CSS element beside the viewer (see
  // `updateMapColorbar`), not NiiVue's own on-canvas one — this vendored
  // build only draws that horizontally, along the canvas's bottom edge, with
  // no vertical/right-side option.
  vol.colorbarVisible = false;
  vol.calculateRAS();
  // `NVImage.zerosLike` clones `template` (the acquired image) before
  // zeroing it, and `clone()` runs the library's own `calMinMax()` over the
  // *template's* data as a side effect — so `hdr.cal_min`/`hdr.cal_max` start
  // out describing the wrong image entirely. Set both the plain property and
  // its header twin to our percentile window, so whichever one a later
  // render/add-volume step reads back gets the fitted map's own range.
  vol.cal_min = roundBound(lo);
  vol.cal_max = roundBound(hi);
  vol.hdr.cal_min = vol.cal_min;
  vol.hdr.cal_max = vol.cal_max;
  return vol;
}

// In BIDS one file is one 3D volume, while the viewer, the frame slider and
// `readVolumeSeries` all expect a single 4D image.
//
// Rather than assemble an NVImage by hand — which means setting NiiVue's
// internal 4D bookkeeping correctly and keeping it correct — concatenate the
// volumes into a real 4D NIfTI and let NiiVue parse it, the same path the
// pre-baked 4D bundles take. Reading the few header fields needed to do that is
// the only NIfTI field access this file performs; decoding is still NiiVue's.
//
// `parts` are the per-volume file bytes in the order resolution put them, which
// is the order the model consumes them.
function buildSeriesNifti(parts) {
  const raw = parts.map((b) => (b[0] === 0x1f && b[1] === 0x8b ? gunzipSync(b) : b));
  const head = new DataView(raw[0].buffer, raw[0].byteOffset, raw[0].byteLength);
  // dim[0] (the dimensionality) is 1..7 in the file's own byte order; anything
  // else means the header is big-endian, which nothing this project writes.
  const ndim = head.getInt16(40, true);
  if (ndim < 1 || ndim > 7) {
    throw new Error("unsupported NIfTI byte order (big-endian header)");
  }
  const voxOffset = head.getFloat32(108, true);
  const bitpix = head.getInt16(72, true);
  const [nx, ny, nz] = [1, 2, 3].map((i) => head.getInt16(40 + i * 2, true));
  const frameBytes = nx * ny * nz * (bitpix / 8);
  const nt = raw.length;

  const header = raw[0].slice(0, voxOffset);
  const hv = new DataView(header.buffer, header.byteOffset, header.byteLength);
  hv.setInt16(40, 4, true); // dim[0]: now four-dimensional
  hv.setInt16(48, nt, true); // dim[4]: this many volumes

  const out = new Uint8Array(voxOffset + frameBytes * nt);
  out.set(header, 0);
  for (let t = 0; t < nt; t++) {
    const data = raw[t].subarray(voxOffset, voxOffset + frameBytes);
    if (data.length !== frameBytes) {
      throw new Error(
        `volume ${t + 1} of ${nt} holds ${data.length} data bytes, expected ${frameBytes} ` +
          "(the volumes of one collection must share a shape and datatype)",
      );
    }
    out.set(data, voxOffset + frameBytes * t);
  }
  return { bytes: out, nx, ny, nz, nt };
}

// The two viewer wraps are equal-width grid columns, stretched (CSS
// `align-items: stretch`) to the grid row's full height, with `.viewer`
// flexed to fill that in turn — so both viewers are always exactly the same
// size, whatever space the page has to give them. NiiVue fits a slice inside
// whatever box it is given, preserving the data's own aspect ratio (fit-to-
// contain, like an `object-fit: contain` image), so the box itself does not
// need to match the data's aspect ratio the way it used to.
function sizeViewers() {
  nvIn.resizeListener();
  nvOut.resizeListener();
}

function setFrameUi(nt, labels) {
  const slider = $("frame");
  slider.max = String(Math.max(0, nt - 1));
  slider.value = "0";
  slider.disabled = nt <= 1;
  $("frame-label").textContent = labels[0] ?? "";
}

// ---------------------------------------------------------------------------
// A reader's own BIDS data, dropped onto the page. Everything past "turn this
// into a path -> bytes map" is the fetched path's code, unchanged: the same
// `resolve_bids`, the same loading, the same fit. That identity is the point —
// there is no separate code path for "our demo data" and "your data".

// Walk a dropped directory entry into `[path, File]` pairs. The File System
// Entry API is callback-based and its `readEntries` returns at most 100 entries
// per call, so it must be drained in a loop.
async function walkEntry(entry, prefix = "") {
  const path = prefix ? `${prefix}/${entry.name}` : entry.name;
  if (entry.isFile) {
    const file = await new Promise((res, rej) => entry.file(res, rej));
    return [[path, file]];
  }
  const reader = entry.createReader();
  const children = [];
  for (;;) {
    const batch = await new Promise((res, rej) => reader.readEntries(res, rej));
    if (batch.length === 0) break;
    children.push(...batch);
  }
  const nested = await Promise.all(children.map((c) => walkEntry(c, path)));
  return nested.flat();
}

// The dataset root is wherever `dataset_description.json` sits — the file BIDS
// defines the root by. Paths are rewritten relative to it, so a folder dropped
// from anywhere resolves the same as an unzipped archive.
function rootRelative(pairs) {
  const marker = pairs
    .map(([p]) => p)
    .filter((p) => p.endsWith("dataset_description.json"))
    .sort((a, b) => a.length - b.length)[0];
  if (!marker) {
    throw new Error(
      "no dataset_description.json found — a BIDS dataset root must contain one",
    );
  }
  const root = marker.slice(0, marker.length - "dataset_description.json".length);
  return pairs
    .filter(([p]) => p.startsWith(root))
    .map(([p, f]) => [p.slice(root.length), f]);
}

// `entries` must be captured synchronously from the drop event: a
// `DataTransfer`'s items are neutered once the handler returns.
async function filesFromDrop(entries) {
  // A single dropped archive is the fetched path's own input, so reuse it.
  if (entries.length === 1 && entries[0].isFile && /\.zip$/i.test(entries[0].name)) {
    const file = await new Promise((res, rej) => entries[0].file(res, rej));
    return unzipDataset(new Uint8Array(await file.arrayBuffer()));
  }

  const pairs = (await Promise.all(entries.map((e) => walkEntry(e)))).flat();
  if (pairs.length === 0) throw new Error("nothing readable in that drop");
  const files = new Map();
  for (const [path, file] of rootRelative(pairs)) {
    files.set(path, new Uint8Array(await file.arrayBuffer()));
  }
  return files;
}

// Which registered models can fit this dataset. Asking every model, rather than
// assuming the selected one, is what lets a reader drop a folder and be told
// what it is — including when it is nothing this playground knows.
async function modelsMatching(files) {
  const matches = [];
  for (const name of modelNames) {
    const meta = await loadBundle(name);
    try {
      if (wasm.resolve_bids(files, meta.config_bids, "").length > 0) matches.push(name);
    } catch {
      // A model whose resolution throws simply does not match this dataset.
    }
  }
  return matches;
}

async function loadDropped(entries) {
  showLoading("Reading your dataset…", 16);
  try {
    await useDataset(await filesFromDrop(entries));
  } catch (e) {
    endLoading();
    renderFilesError(`Could not read that dataset — ${e.message}`);
    status(`Could not read that dataset — ${e.message}`, "error");
  }
}

// A reader's dataset, however it arrived: find which models can fit it, load it
// through the ordinary path, or explain per file why nothing matched.
async function useDataset(files) {
  stage(`Resolving your ${files.size} files as BIDS…`);
  const matches = await modelsMatching(files);
  if (matches.length === 0) {
    // Explain it against the model currently selected, since that is the one
    // the reader was looking at when they handed the dataset over.
    const meta = await loadBundle($("model").value);
    const verdicts = wasm.annotate_non_matching(files, meta.config_bids);
    dataset = { archive: "your dataset", files, resolved: { files: verdicts } };
    endLoading();
    renderFiles();
    $("files-summary").textContent =
      `your dataset · ${verdicts.length} files · no model here can fit this`;
    showInputsTab("files");
    status("No model matches that dataset — see Files for why", "error");
    return;
  }

  // Pinning the dataset lets the ordinary load path pick it up instead of
  // fetching, so nothing downstream knows where it came from.
  const pick = matches.includes($("model").value) ? $("model").value : matches[0];
  droppedFiles = files;
  $("model").value = pick;
  endLoading();
  await loadModel(pick);
  const others = matches.filter((m) => m !== pick);
  if (others.length) {
    status(`Loaded as ${pick} — also matches ${others.join(", ")}`, "info");
  }
}

// Turn `<input type="file">` output into the same path -> bytes map a drop
// produces. A directory picker reports each file's `webkitRelativePath`, which
// is exactly the relative path resolution needs; a picked `.zip` goes through
// the same extractor a fetched archive does.
async function filesFromInput(fileList) {
  const picked = [...fileList];
  if (picked.length === 0) throw new Error("nothing selected");
  if (picked.length === 1 && /\.zip$/i.test(picked[0].name)) {
    return unzipDataset(new Uint8Array(await picked[0].arrayBuffer()));
  }
  const pairs = picked.map((f) => [f.webkitRelativePath || f.name, f]);
  const files = new Map();
  for (const [path, file] of rootRelative(pairs)) {
    files.set(path, new Uint8Array(await file.arrayBuffer()));
  }
  return files;
}

async function onBrowse(fileList) {
  if (!wasm) {
    status("Fitting unavailable — wasm failed to load", "error");
    return;
  }
  showLoading("Reading your dataset…", 16);
  try {
    await useDataset(await filesFromInput(fileList));
  } catch (e) {
    endLoading();
    renderFilesError(`Could not read that dataset — ${e.message}`);
    status(`Could not read that dataset — ${e.message}`, "error");
  }
}

function onDrop(event) {
  event.preventDefault();
  $("drop-wrap").classList.remove("drop-over");
  if (!wasm) {
    status("Fitting unavailable — wasm failed to load", "error");
    return;
  }
  // Capture the entries here, synchronously: the DataTransfer is neutered as
  // soon as this handler returns, so nothing async may touch it.
  const entries = [...event.dataTransfer.items]
    .map((i) => (i.webkitGetAsEntry ? i.webkitGetAsEntry() : null))
    .filter(Boolean);
  if (entries.length === 0) {
    status("That drop carried no files", "error");
    return;
  }
  loadDropped(entries);
}

// ---------------------------------------------------------------------------
// Files panel: the dataset as resolution saw it. Every verdict arrives as data
// from `resolve_bids`; this only chooses how to draw it, and branches on the
// verdict's shape alone — never on a model, suffix, or parameter name.

// The Inputs card shows either the image or where the image came from.
function showInputsTab(tab) {
  const isViewer = tab === "viewer";
  $("tab-viewer").classList.toggle("active", isViewer);
  $("tab-files").classList.toggle("active", !isViewer);
  $("tab-viewer").setAttribute("aria-selected", String(isViewer));
  $("tab-files").setAttribute("aria-selected", String(!isViewer));
  $("viewer-in").hidden = !isViewer;
  $("files-view").hidden = isViewer;
  // The canvas was display:none while hidden, so its GL viewport is stale.
  // Skip while loading: the skeleton is over it and there is nothing to resize.
  if (isViewer && !loading) sizeViewers();
}

// While a dataset is being fetched, extracted and resolved there is nothing
// truthful to list, so both views show the shape of what is coming rather than a
// stale list or an empty black canvas. `expect` is the file count if known.
function showLoading(note, expect = 12) {
  loading = true;
  // Both viewers shimmer: the fitted map has nothing to show until a fit runs,
  // and during a load it has no dataset to run against either. The overlays sit
  // inside their viewers, so neither card changes size.
  $("skel-in").hidden = false;
  $("skel-out").hidden = false;
  const tree = $("files-tree");
  tree.replaceChildren();
  $("files-summary").textContent = note;
  const dir = document.createElement("div");
  dir.className = "skel skel-dir";
  tree.append(dir);
  for (let i = 0; i < expect; i++) {
    const row = document.createElement("div");
    row.className = "skel-row";
    const name = document.createElement("div");
    // Vary the width a little so the block reads as a list of names rather
    // than a grid.
    name.className = "skel skel-name";
    name.style.maxWidth = `${55 + ((i * 37) % 40)}%`;
    const role = document.createElement("div");
    role.className = "skel skel-role";
    row.append(name, role);
    tree.append(row);
  }
}

// Leaves whichever tab the reader is on selected, now that it has real content.
function endLoading() {
  loading = false;
  hideDownloadProgress();
  $("skel-in").hidden = true;
  $("skel-out").hidden = true;
  const onFiles = $("tab-files").classList.contains("active");
  showInputsTab(onFiles ? "files" : "viewer");
}

// Slice or multiplanar, for the fitted map. Only meaningful for a volumetric
// map: a single-slice fit has no second or third plane, so the toggle disables
// itself rather than offering a view that would show two empty strips.
function showMapView(view) {
  const planes = view === "planes";
  $("tab-slice").classList.toggle("active", !planes);
  $("tab-planes").classList.toggle("active", planes);
  $("tab-slice").setAttribute("aria-selected", String(!planes));
  $("tab-planes").setAttribute("aria-selected", String(planes));
  nvOut.setSliceType(planes ? nvOut.sliceTypeMultiplanar : nvOut.sliceTypeAxial);
  nvOut.drawScene();
}

// True when the fitted map has more than one slice to show.
function mapIsVolumetric() {
  return (current?.meta?.dims?.[2] ?? 1) > 1;
}

function syncMapViewControls() {
  const volumetric = mapIsVolumetric();
  const haveMap = outputVolumes.length > 0;
  $("tab-planes").disabled = !volumetric;
  $("tab-planes").title = volumetric
    ? "Show all three planes"
    : "This fit is a single slice — there are no other planes";
  $("open-map-modal").disabled = !haveMap;
  // Nothing to measure until a map exists.
  $("roi-toggle").disabled = !haveMap;
  if (!haveMap && roiDrawing) toggleRoi();
  if (!volumetric) showMapView("slice");
}

// The fitted map in a modal, at a size the side-by-side layout cannot give it.
// Reuses the same single NiiVue instance the file viewer uses, for the same
// WebGL-context reason.
async function openMapModal() {
  const shown = outputVolumes.find((o) => o.name === shownOutput) ?? outputVolumes[0];
  if (!shown) return;
  $("file-modal").hidden = false;
  $("file-modal-title").textContent = `${shown.name}${shown.unit ? ` [${shown.unit}]` : ""}`;
  await ensureModalViewer();
  for (const v of [...nvModal.volumes]) nvModal.removeVolume(v);
  nvModal.addVolume(shown.volume);
  nvModal.setSliceType(
    mapIsVolumetric() ? nvModal.sliceTypeMultiplanar : nvModal.sliceTypeAxial,
  );
  nvModal.resizeListener();
  nvModal.drawScene();
  // A quantitative map is unreadable without a scale, so the modal always shows
  // one — with the histogram, so the window can be judged against the data.
  $("level").hidden = false;
  levelModal ??= createLevelControl("level");
  levelModal.open(shown, lastMaps?.[shown.name] ?? []);
  nvModal.resizeListener();
  nvModal.drawScene();
}

function roleLabel(role) {
  switch (role.kind) {
    case "volume": {
      const detail = identityLabel(role.identity);
      const n = `volume ${role.index + 1} of ${role.total}`;
      return detail === "volume" ? n : `${n} · ${detail}`;
    }
    case "sidecar":
      return role.applies_to.length === 1
        ? "sidecar → 1 volume"
        : `sidecar → ${role.applies_to.length} volumes`;
    case "mask":
      return "mask";
    case "aux":
      return role.input;
    case "dataset_metadata":
      return "dataset metadata";
    case "unused":
      return role.reason;
    default:
      return role.kind;
  }
}

// Group by directory, preserving path order. Directory order, not resolution
// order: this is a file browser, so the dataset's real layout is what it shows —
// a volume's position on the model's axis is in its label. For a named model the
// two genuinely disagree, and reordering rows would misrepresent the directory.
function groupByDir(files) {
  const dirs = new Map();
  for (const [path, role] of files) {
    const cut = path.lastIndexOf("/");
    const dir = cut === -1 ? "" : path.slice(0, cut);
    const name = cut === -1 ? path : path.slice(cut + 1);
    if (!dirs.has(dir)) dirs.set(dir, []);
    dirs.get(dir).push({ path, name, role });
  }
  return dirs;
}

const VIEWABLE = ["volume", "mask", "aux"];

function renderFiles() {
  const tree = $("files-tree");
  tree.replaceChildren();
  if (!dataset?.resolved?.files) {
    $("files-summary").textContent = dataset
      ? "No per-file verdicts for this dataset."
      : "Showing the pre-baked demo slice — no BIDS dataset loaded.";
    return;
  }
  const entries = dataset.resolved.files;
  const counts = new Map();
  for (const [, role] of entries) counts.set(role.kind, (counts.get(role.kind) ?? 0) + 1);
  const parts = [...counts].map(([k, n]) => `${n} ${k.replace(/_/g, " ")}`);
  $("files-summary").textContent =
    `${dataset.archive} · ${entries.length} files · ${parts.join(" · ")}`;

  for (const [dir, rows] of groupByDir(entries)) {
    const head = document.createElement("div");
    head.className = "files-dir";
    head.textContent = dir === "" ? "./" : `${dir}/`;
    tree.append(head);
    for (const { path, name, role } of rows) {
      const row = document.createElement("div");
      row.className = `files-row ${role.kind}`;
      row.dataset.path = path;
      if (role.kind === "volume") {
        row.dataset.frame = String(role.index);
        row.classList.add("clickable");
        row.title = "Click to show this volume";
      }
      const label = document.createElement("span");
      label.className = "files-name";
      label.textContent = name;
      const kind = document.createElement("span");
      kind.className = "files-role";
      kind.textContent = roleLabel(role);
      row.append(label, kind);
      if (VIEWABLE.includes(role.kind) && dataset.files?.has(path)) {
        const open = document.createElement("button");
        open.className = "files-open";
        open.textContent = "⤢";
        open.title = "Open this file in a viewer";
        open.addEventListener("click", (e) => {
          e.stopPropagation();
          openFileModal(path);
        });
        row.append(open);
        row.addEventListener("dblclick", () => openFileModal(path));
      }
      tree.append(row);
    }
  }
  syncFilesHighlight();
}

// The row and the frame slider drive the same state, so a filename and the
// image it produced are one click apart.
function onFilesClick(event) {
  const row = event.target.closest(".files-row");
  if (!row?.dataset.frame) return;
  goToFrame(Number(row.dataset.frame));
}

function syncFilesHighlight() {
  const frame = String(current?.frame ?? 0);
  for (const row of $("files-tree").querySelectorAll(".files-row")) {
    row.classList.toggle("current", row.dataset.frame === frame);
  }
}

// Failures show in the panel as well as the status bar: this is where a reader
// looks for why nothing appeared.
function renderFilesError(message) {
  $("files-tree").replaceChildren();
  $("files-summary").textContent = message;
  showInputsTab("files");
}

// One NiiVue instance, created on first open and reused. Each holds a WebGL
// context and browsers cap those, so constructing one per open would leak
// contexts until the other viewers stopped rendering.
let nvModal = null;

// ---------------------------------------------------------------------------
// Window/level control: the map's value histogram beside a colour bar whose two
// handles are the display window. The histogram is what makes a bad window
// diagnosable — you can see where the tissue sits relative to where the scale
// currently ends.
//
// One widget, instantiated per place it appears (the fitted-map panel and the
// modal), so both behave identically rather than drifting apart.

const HIST_BINS = 64;

// Bin the finite values. NaN (unfitted) voxels are excluded: a histogram of "no
// data" says nothing about the window.
function buildHistogram(values, lo, hi) {
  const bins = new Float64Array(HIST_BINS);
  const span = hi - lo;
  if (!(span > 0)) return bins;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (!Number.isFinite(v)) continue;
    let b = Math.floor(((v - lo) / span) * HIST_BINS);
    // The maximum lands exactly on `HIST_BINS`; it belongs in the top bin.
    if (b === HIST_BINS) b = HIST_BINS - 1;
    if (b < 0 || b >= HIST_BINS) continue;
    bins[b] += 1;
  }
  return bins;
}

// `prefix` names this instance's elements: `<prefix>-hist`, `-bar`, `-grad`,
// `-lo`, `-hi`, `-readout`.
function createLevelControl(prefix) {
  const el = (part) => $(`${prefix}-${part}`);
  // { dataMin, dataMax, bins, unit } — the data behind the current histogram.
  let data = null;

  const frac = (v) => (v - data.dataMin) / (data.dataMax - data.dataMin || 1);
  const value = (f) => data.dataMin + f * (data.dataMax - data.dataMin);

  function drawHistogram() {
    const canvas = el("hist");
    const ctx = canvas.getContext("2d");
    const { width: w, height: h } = canvas;
    ctx.clearRect(0, 0, w, h);
    if (!data || !shownOutput) return;

    // A log scale keeps a long tail visible: a background peak orders of
    // magnitude above the tissue would otherwise flatten everything else.
    const scaled = Array.from(data.bins, (c) => Math.log10(1 + c));
    const peak = Math.max(...scaled, 1e-9);
    const barH = h / HIST_BINS;
    const style = getComputedStyle(document.documentElement);
    const inWindow = style.getPropertyValue("--accent").trim() || "#38c0cf";
    const outWindow = style.getPropertyValue("--line").trim() || "#232c37";
    const span = data.dataMax - data.dataMin;
    const lo = shownOutput.volume.cal_min;
    const hi = shownOutput.volume.cal_max;

    for (let b = 0; b < HIST_BINS; b++) {
      const binLo = data.dataMin + (b / HIST_BINS) * span;
      const binHi = data.dataMin + ((b + 1) / HIST_BINS) * span;
      // Bins inside the window are highlighted, so the window's effect on the
      // data is visible rather than implied.
      ctx.fillStyle = binHi >= lo && binLo <= hi ? inWindow : outWindow;
      const len = (scaled[b] / peak) * (w - 2);
      // Low values at the bottom, matching the colour bar's orientation.
      ctx.fillRect(w - len, h - (b + 1) * barH, len, Math.max(1, barH - 0.5));
    }
  }

  function paint() {
    if (!shownOutput) {
      el("grad").style.background = "none";
      return;
    }
    const lut = nvOut.colormap($("colormap").value || "gray");
    const stops = [];
    for (let i = 0; i <= 32; i++) {
      const px = Math.round((i / 32) * 255) * 4;
      stops.push(`rgb(${lut[px]}, ${lut[px + 1]}, ${lut[px + 2]})`);
    }
    // Low value at the bottom, high at the top — the usual vertical convention,
    // matching the committed docsfig figures.
    el("grad").style.background = `linear-gradient(to top, ${stops.join(", ")})`;

    if (!data) return;
    for (const [part, v] of [
      ["lo", shownOutput.volume.cal_min],
      ["hi", shownOutput.volume.cal_max],
    ]) {
      const handle = el(part);
      handle.style.bottom = `${Math.max(0, Math.min(1, frac(v))) * 100}%`;
      handle.style.top = "auto";
      handle.style.transform = "translateY(50%)";
      handle.querySelector("span").textContent =
        `${roundBound(v)}${data.unit ? ` ${data.unit}` : ""}`;
      handle.setAttribute("aria-valuenow", String(roundBound(v)));
    }
    drawHistogram();
  }

  function beginDrag(which, event) {
    if (!data || !shownOutput) return;
    event.preventDefault();
    const handle = el(which);
    handle.classList.add("dragging");
    const move = (e) => {
      const r = el("bar").getBoundingClientRect();
      const f = Math.max(0, Math.min(1, (r.bottom - e.clientY) / r.height));
      const v = value(f);
      // The handles may not cross: a window needs a floor below its ceiling.
      const gap = (data.dataMax - data.dataMin) / 200;
      if (which === "lo") setWindow(Math.min(v, shownOutput.volume.cal_max - gap), null);
      else setWindow(null, Math.max(v, shownOutput.volume.cal_min + gap));
    };
    const up = () => {
      handle.classList.remove("dragging");
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  }

  // Arrow keys nudge a handle, so the window is reachable without a pointer.
  function onKey(which, event) {
    if (!data || !shownOutput) return;
    const step = (data.dataMax - data.dataMin) / 100;
    const delta = { ArrowUp: step, ArrowRight: step, ArrowDown: -step, ArrowLeft: -step }[
      event.key
    ];
    if (delta === undefined) return;
    event.preventDefault();
    const gap = (data.dataMax - data.dataMin) / 200;
    if (which === "lo") {
      setWindow(
        Math.min(shownOutput.volume.cal_min + delta, shownOutput.volume.cal_max - gap),
        null,
      );
    } else {
      setWindow(
        null,
        Math.max(shownOutput.volume.cal_max + delta, shownOutput.volume.cal_min + gap),
      );
    }
  }

  function onHover(event) {
    if (!data) return;
    const r = el("bar").getBoundingClientRect();
    const f = Math.max(0, Math.min(1, (r.bottom - event.clientY) / r.height));
    const readout = el("readout");
    readout.hidden = false;
    readout.style.bottom = `${f * 100}%`;
    readout.textContent = `${roundBound(value(f))}${data.unit ? ` ${data.unit}` : ""}`;
  }

  // Click a bound's label to type an exact value, for when dragging is not
  // precise enough. The input replaces the label in place and commits on Enter
  // or blur; Escape abandons it.
  function editBound(which) {
    if (!shownOutput || el(which).querySelector("input")) return;
    const handle = el(which);
    const label = handle.querySelector("span");
    const current = which === "lo" ? shownOutput.volume.cal_min : shownOutput.volume.cal_max;
    const input = document.createElement("input");
    input.type = "number";
    input.step = "any";
    input.className = "level-edit";
    input.value = String(roundBound(current));
    label.style.visibility = "hidden";
    handle.append(input);
    input.focus();
    input.select();
    const finish = (commit) => {
      if (commit) {
        const v = Number(input.value);
        if (Number.isFinite(v)) {
          if (which === "lo") setWindow(Math.min(v, shownOutput.volume.cal_max), null);
          else setWindow(null, Math.max(v, shownOutput.volume.cal_min));
        }
      }
      input.remove();
      label.style.visibility = "";
      paint();
    };
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") finish(true);
      if (e.key === "Escape") finish(false);
      // A drag handler on the parent must not see these.
      e.stopPropagation();
    });
    input.addEventListener("blur", () => finish(true));
    // Typing in the input must not start a handle drag.
    input.addEventListener("pointerdown", (e) => e.stopPropagation());
  }
  for (const which of ["lo", "hi"]) {
    el(which).querySelector("span").addEventListener("pointerdown", (e) => {
      // `stopPropagation` keeps the handle's drag from starting; `preventDefault`
      // is what makes the edit survive — without it the gesture's default action
      // moves focus to the handle (it is `tabindex=0`), which blurs the new input
      // and commits it before a key can be typed.
      e.stopPropagation();
      e.preventDefault();
      editBound(which);
    });
  }

  el("lo").addEventListener("pointerdown", (e) => beginDrag("lo", e));
  el("hi").addEventListener("pointerdown", (e) => beginDrag("hi", e));
  el("lo").addEventListener("keydown", (e) => onKey("lo", e));
  el("hi").addEventListener("keydown", (e) => onKey("hi", e));
  el("bar").addEventListener("pointermove", onHover);
  el("bar").addEventListener("pointerleave", () => {
    el("readout").hidden = true;
  });

  return {
    // Mark where a value sits on the scale — `null` clears the marker. This is
    // what ties a point in the image to a number on the colour bar.
    mark(v) {
      const dot = el("dot");
      if (!data || v === null || !Number.isFinite(v)) {
        dot.hidden = true;
        return;
      }
      const f = frac(v);
      // Outside the data's own extent there is no place on the bar for it.
      if (f < 0 || f > 1) {
        dot.hidden = true;
        return;
      }
      dot.hidden = false;
      dot.style.bottom = `${f * 100}%`;
      dot.querySelector("span").textContent =
        `${roundBound(v)}${data.unit ? ` ${data.unit}` : ""}`;
    },
    // The histogram spans the *data's* extent, wider than the display window, so
    // a window can be widened as well as narrowed.
    open(entry, values) {
      // One pass, no intermediate array and no spread: a whole-brain map runs to
      // millions of voxels, and `Math.min(...values)` on that many arguments
      // overflows the call stack.
      let dataMin = Infinity;
      let dataMax = -Infinity;
      let n = 0;
      for (let i = 0; i < values.length; i++) {
        const v = values[i];
        if (!Number.isFinite(v)) continue;
        if (v < dataMin) dataMin = v;
        if (v > dataMax) dataMax = v;
        n += 1;
      }
      if (n === 0) {
        data = null;
        drawHistogram();
        return;
      }
      // Include the current window, so both handles are always reachable.
      dataMin = Math.min(dataMin, entry.volume.cal_min);
      dataMax = Math.max(dataMax, entry.volume.cal_max);
      if (!(dataMax > dataMin)) dataMax = dataMin + 1;
      data = { dataMin, dataMax, unit: entry.unit, bins: buildHistogram(values, dataMin, dataMax) };
      // Match the canvas backing store to its laid-out size, or bars stretch.
      const canvas = el("hist");
      const box = canvas.getBoundingClientRect();
      if (box.width > 0) {
        canvas.width = Math.round(box.width);
        canvas.height = Math.max(80, Math.round(box.height));
      }
      paint();
    },
    paint,
    hasData: () => data !== null,
  };
}

let levelMain = null;
let levelModal = null;

// ---------------------------------------------------------------------------
// ROI statistics. NiiVue's own pen writes into a drawing bitmap the same shape
// as the volume, so "the voxels beneath the ROI" is just the fitted map sampled
// where that bitmap is non-zero — no geometry of our own to get wrong.

let roiDrawing = false;

// Summary statistics of `values`, which must already be the in-ROI finite set.
// Quartiles use the same linear-interpolation convention as `percentileWindow`,
// so a reader comparing the two sees consistent numbers.
function describeValues(values) {
  const v = Float64Array.from(values).sort();
  const n = v.length;
  const at = (p) => {
    const idx = (p / 100) * (n - 1);
    const lo = Math.floor(idx);
    const hi = Math.ceil(idx);
    return lo === hi ? v[lo] : v[lo] + (v[hi] - v[lo]) * (idx - lo);
  };
  const mean = v.reduce((a, b) => a + b, 0) / n;
  // Sample standard deviation (n-1): these voxels are a sample of a region, not
  // the whole population of it.
  const sd =
    n > 1 ? Math.sqrt(v.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1)) : 0;
  const q1 = at(25);
  const q3 = at(75);
  return { n, mean, sd, min: v[0], max: v[n - 1], median: at(50), q1, q3, iqr: q3 - q1 };
}

// Sample the shown map wherever the drawing bitmap is set. NiiVue's bitmap is in
// the volume's own voxel order, which is the order `buildMapVolume` wrote — so
// index `i` is the same voxel in both.
function roiValues() {
  const bitmap = nvOut.drawBitmap;
  if (!bitmap || !shownOutput || !lastMaps) return [];
  const flat = lastMaps[shownOutput.name];
  if (!flat) return [];
  const [nx, ny, nz] = current.meta.dims;
  const out = [];
  for (let z = 0; z < nz; z++) {
    for (let y = 0; y < ny; y++) {
      for (let x = 0; x < nx; x++) {
        // The bitmap is NiiVue's x-fastest order; `lastMaps` is C-order
        // [nx,ny,nz] (see `readVolumeSeries`), so each needs its own index.
        if (bitmap[x + y * nx + z * nx * ny] === 0) continue;
        const v = flat[(x * ny + y) * nz + z];
        if (Number.isFinite(v)) out.push(v);
      }
    }
  }
  return out;
}

function renderRoiStats() {
  const box = $("roi-stats");
  if (!roiDrawing && !nvOut.drawBitmap) {
    box.hidden = true;
    return;
  }
  box.hidden = false;
  const values = roiValues();
  box.replaceChildren();
  if (values.length === 0) {
    const empty = document.createElement("div");
    empty.className = "roi-empty";
    empty.textContent = "Draw on the map to measure a region.";
    box.append(empty);
    return;
  }
  const s = describeValues(values);
  const unit = shownOutput?.unit ? ` ${shownOutput.unit}` : "";
  const rows = [
    ["voxels", String(s.n)],
    ["mean", `${roundBound(s.mean)}${unit}`],
    ["SD", `${roundBound(s.sd)}${unit}`],
    ["median", `${roundBound(s.median)}${unit}`],
    ["min", `${roundBound(s.min)}${unit}`],
    ["max", `${roundBound(s.max)}${unit}`],
    ["IQR", `${roundBound(s.iqr)}${unit}`],
    ["Q1–Q3", `${roundBound(s.q1)} – ${roundBound(s.q3)}`],
  ];
  for (const [label, value] of rows) {
    const row = document.createElement("div");
    row.className = "roi-stat";
    const k = document.createElement("span");
    k.textContent = label;
    const val = document.createElement("b");
    val.textContent = value;
    row.append(k, val);
    box.append(row);
  }
}

function toggleRoi() {
  roiDrawing = !roiDrawing;
  nvOut.setDrawingEnabled(roiDrawing);
  if (roiDrawing) nvOut.setPenValue(1, true);
  $("roi-toggle").classList.toggle("active", roiDrawing);
  $("roi-toggle").textContent = roiDrawing ? "✎ drawing…" : "✎ draw ROI";
  $("roi-clear").hidden = !roiDrawing;
  // Drawing and drag-to-window are the same gesture, so one must yield while the
  // pen is active.
  nvOut.opts.dragMode = roiDrawing ? DRAG_MODE.none : DRAG_MODE.contrast;
  renderRoiStats();
}

function clearRoi() {
  nvOut.drawBitmap = null;
  nvOut.updateGLVolume();
  nvOut.drawScene();
  renderRoiStats();
}

// The one place a display window is changed. Every control routes through here,
// so the number inputs, both sets of handles, and the reset button cannot drift
// apart in what they update. `null` leaves that bound alone.
function setWindow(min, max) {
  if (!shownOutput) return;
  const vol = shownOutput.volume;
  if (min !== null && Number.isFinite(min)) vol.cal_min = min;
  if (max !== null && Number.isFinite(max)) vol.cal_max = max;
  // Both the plain property and its header twin: different NiiVue paths read
  // different ones (see `buildMapVolume`).
  vol.hdr.cal_min = vol.cal_min;
  vol.hdr.cal_max = vol.cal_max;
  nvOut.updateGLVolume();
  nvOut.drawScene();
  if (nvModal && nvModal.volumes.length) {
    nvModal.updateGLVolume();
    nvModal.drawScene();
  }
  levelMain?.paint();
  levelModal?.paint();
}

async function ensureModalViewer() {
  if (nvModal) return;
  nvModal = new Niivue({
    isResizeCanvas: true,
    backColor: [0.02, 0.02, 0.03, 1],
    loadingText: "",
  });
  await nvModal.attachTo("gl-modal");
  nvModal.setHighResolutionCapable(true);
  nvModal.canvas.addEventListener("mousemove", onMapHover);
  nvModal.canvas.addEventListener("mouseleave", clearMapHover);
}

async function openFileModal(path) {
  if (!dataset?.files?.has(path)) {
    status(`No data held for "${path}"`, "error");
    return;
  }
  $("file-modal").hidden = false;
  $("file-modal-title").textContent = path;
  // An acquired image has no quantitative scale to level, unlike a fitted map.
  $("level").hidden = true;
  await ensureModalViewer();
  for (const v of [...nvModal.volumes]) nvModal.removeVolume(v);
  const volume = await volumeFromDataset(dataset.files, path, { colormap: "gray" });
  nvModal.addVolume(volume);
  // Slice type from the data, never from which dataset this is: a single-slice
  // volume has no second or third plane to show.
  const nz = volume.hdr?.dims?.[3] ?? 1;
  nvModal.setSliceType(nz > 1 ? nvModal.sliceTypeMultiplanar : nvModal.sliceTypeAxial);
  nvModal.resizeListener();
  nvModal.drawScene();
}

function closeFileModal() {
  $("file-modal").hidden = true;
}

// Load one file's bytes out of the extracted archive as an NVImage. NiiVue
// infers the format from the name, so the basename must survive.
async function volumeFromDataset(files, path, extra = {}) {
  const bytes = files.get(path);
  if (!bytes) throw new Error(`resolution named "${path}", which the archive does not hold`);
  const name = path.split("/").pop();
  return NVImage.loadFromFile({ file: new File([bytes], name), name, ...extra });
}

// Fetch → unzip → resolve → load → ready to fit. Returns false when the dataset
// holds nothing this model can fit, having already explained that in the panel;
// throws when the fetch or the archive itself failed.
async function loadModelFromBids(name, meta) {
  const ds = await fetchDataset(name, meta);
  if (ds.collections.length === 0) {
    const files = wasm.annotate_non_matching(ds.files, meta.config_bids);
    dataset = { ...ds, resolved: { files } };
    renderFiles();
    $("files-summary").textContent =
      `${ds.archive} · ${files.length} files · nothing this model can fit`;
    showInputsTab("files");
    status(`No ${meta.title} data in that dataset — see Files for why`, "error");
    return false;
  }

  const resolved = ds.collections[0];
  dataset = { ...ds, resolved };
  // The recipe for BIDS input carries options only; the acquisition comes from
  // the sidecars, via `resolved.protocol_json`.
  setEditorText(meta.config_bids);

  stage(`Loading ${resolved.data_files.length} volumes…`);
  const parts = resolved.data_files.map((path) => {
    const bytes = ds.files.get(path);
    if (!bytes) throw new Error(`resolution named "${path}", which the archive does not hold`);
    return bytes;
  });
  const { bytes, nx, ny, nz, nt } = buildSeriesNifti(parts);
  const volume = await NVImage.loadFromFile({
    file: new File([bytes], `${meta.model}.nii`),
    name: meta.model,
    colormap: "gray",
    colorbarVisible: false,
  });
  nvIn.addVolume(volume);

  let maskU8 = null;
  if (resolved.mask_file) {
    maskU8 = readMask(await volumeFromDataset(ds.files, resolved.mask_file), nx, ny, nz);
  }
  const auxFlat = {};
  const auxVolumes = {};
  for (const [auxName, path] of resolved.aux_files) {
    const auxVolume = await volumeFromDataset(ds.files, path);
    auxFlat[auxName] = Array.from(readScalarVolume(auxVolume, nx, ny, nz));
    auxVolumes[auxName] = auxVolume;
  }

  const ids = JSON.parse(resolved.volume_ids_json);
  const labels = ids.map((id) =>
    identityLabel(typeof id === "string" ? { role: id } : { params: id }),
  );
  // A BIDS-resolved view of this model: the model's own facts come from the
  // payload, everything data-derived from resolution.
  const bidsMeta = {
    ...meta,
    dims: [nx, ny, nz, nt],
    labels,
    volume_ids: ids,
    protocol_json: resolved.protocol_json,
    config: meta.config_bids,
  };

  nvIn.setSliceType(nvIn.sliceTypeAxial);
  nvOut.setSliceType(nvOut.sliceTypeAxial);
  sizeViewers();
  nvIn.drawScene();
  setFrameUi(nt, labels);
  current = { meta: bidsMeta, volume, maskU8, auxFlat, auxVolumes, frame: 0 };
  renderFiles();
  syncMapViewControls();
  $("fit").disabled = false;
  for (const w of resolved.warnings) status(w, "error");
  $("model-info").textContent =
    `${meta.title}: ${nt} volumes, ${nx}×${ny}${nz > 1 ? `×${nz}` : ""} (${resolved.subject})`;
  status("Ready", "ok");
  return true;
}

async function loadModel(name) {
  status(`Loading ${name}…`, "busy");
  let meta;
  try {
    meta = await loadBundle(name);
  } catch (e) {
    status(`Could not load ${name} — ${e.message}`, "error");
    return;
  }

  for (const v of [...nvIn.volumes]) nvIn.removeVolume(v);
  for (const v of [...nvOut.volumes]) nvOut.removeVolume(v);
  outputVolumes = [];
  shownOutput = null;
  lastMaps = null;
  $("output").hidden = true;
  $("output").replaceChildren();
  updateMapColorbar();
  $("voxel-title").textContent = "Voxel — click either viewer";
  $("voxel-value").textContent = "";
  $("model-info").textContent = "";
  $("fit-timing").textContent = "";
  $("curve-note").textContent = "";
  clearCurve();
  enumFields = new Map((meta.enums ?? []).map((e) => [e.key, e.values]));
  wheelAccum = 0;
  dataset = null;

  // The full BIDS dataset is the real thing: fetched, resolved in the browser,
  // and fitted with the acquisition its own sidecars declare. The pre-baked
  // slice is the fallback, for no network or a host that is down.
  if (wasm && meta.archive) {
    // Skeletons rather than a stale list: the file count is unknown until the
    // archive is open, so guess from the volume count the payload declares.
    showLoading(`fetching ${meta.archive}…`, (meta.dims?.[3] ?? 8) * 2 + 4);
    try {
      const ok = await loadModelFromBids(name, meta);
      endLoading();
      if (ok) return;
    } catch (e) {
      endLoading();
      renderFilesError(`${e.message} — showing the pre-baked slice instead`);
      status(`${e.message} — showing the built-in sample instead`, "error");
    }
  }

  setEditorText(meta.config);
  const [nx, ny, nz, nt] = meta.dims;
  let volume, maskVolume;
  try {
    volume = await nvIn.addVolumeFromUrl({
      url: `./data/${meta.files.data}`,
      name: meta.model,
      colormap: "gray",
      colorbarVisible: false,
    });
  } catch (e) {
    status(`Could not load image data — ${e.message}`, "error");
    return;
  }
  let maskU8 = null;
  if (meta.files.mask) {
    try {
      maskVolume = await NVImage.loadFromUrl({ url: `./data/${meta.files.mask}` });
      maskU8 = readMask(maskVolume, nx, ny, nz);
    } catch (e) {
      status(`Could not load the mask — ${e.message}`, "error");
      return;
    }
  }

  // `files.aux` is a general mechanism: whatever auxiliary inputs the recipe
  // resolved (none, one, or several), load every one and hand it to
  // fit_volume (a flat map, for the whole slice) and to forward() (one
  // scalar, for whichever voxel is clicked) — never keyed on a model or aux
  // name.
  const auxFlat = {};
  const auxVolumes = {};
  for (const [auxName, filename] of Object.entries(meta.files.aux ?? {})) {
    try {
      const auxVolume = await NVImage.loadFromUrl({ url: `./data/${filename}` });
      auxFlat[auxName] = Array.from(readScalarVolume(auxVolume, nx, ny, nz));
      auxVolumes[auxName] = auxVolume;
    } catch (e) {
      status(`Could not load ${filename} — ${e.message}`, "error");
      return;
    }
  }

  nvIn.setSliceType(nvIn.sliceTypeAxial);
  nvOut.setSliceType(nvOut.sliceTypeAxial);
  sizeViewers();
  nvIn.drawScene();

  setFrameUi(nt, meta.labels);
  current = { meta, volume, maskU8, auxFlat, auxVolumes, frame: 0 };
  $("fit").disabled = !wasm;
  // The model/volume-count/dims summary lives beside the frame note, not the
  // navbar — the navbar's `#status` is for transient app state (loading,
  // errors, "ready"), not a per-model fact that stays true until the next
  // model switch.
  $("model-info").textContent = `${meta.title}: ${nt} volumes, ${nx}×${ny}`;
  syncMapViewControls();
  status(
    wasm ? "Ready" : "Fitting unavailable — wasm failed to load; viewers still work",
    wasm ? "ok" : "error",
  );
}

function onFrameChange() {
  if (!current) return;
  const t = Number($("frame").value);
  current.frame = t;
  nvIn.setFrame4D(current.volume.id, t);
  $("frame-label").textContent = current.meta.labels[t] ?? "";
  syncFilesHighlight();
}

// Jumps to frame `t` (NiiVue's own `setFrame4D`, the same call `onFrameChange`
// makes from the slider) and syncs the slider + label to match, so the wheel
// and the slider always agree on where they are.
function goToFrame(t) {
  $("frame").value = String(t);
  onFrameChange();
}

// The progress track is a permanent fixture above "Fit slice" (an empty
// track at idle, not an element that appears/disappears and reflows the
// page); only its fill width and the "active" stripe animation change.
function showProgress() {
  $("progress-bar").classList.add("active");
  setProgress(0);
}
function setProgress(pct) {
  $("progress-bar").style.width = `${Math.max(0, Math.min(100, pct))}%`;
}
function hideProgress() {
  $("progress-bar").classList.remove("active");
  setProgress(0);
}
// Lets the browser paint (and stay responsive to input) between fit blocks —
// a plain microtask/`setTimeout(0)` does not reliably yield before the next
// paint in every engine, but a rAF round-trip does.
function nextFrame() {
  return new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 0)));
}

// `fit_volume` is one synchronous call with no progress callback across the
// wasm boundary, so real (not simulated) progress requires splitting the work
// ourselves: fit contiguous row-blocks of the slice — `x` is the slowest-
// varying axis in the C-order `[nx,ny,nz,nt]`/`[nx,ny,nz]` layout `data`/
// `maskU8`/`auxFlat` already use, so a row range is a contiguous subarray —
// and stitch each block's returned maps into the full-size buffers, yielding
// to the event loop between blocks so the progress bar paints and the page
// stays responsive. Each block is an independent voxelwise fit, so the
// stitched result is exactly the single-call result (verified by `probes`).
async function fitVolumeWithProgress(nx, ny, nz, nt, data, maskU8, auxFlat) {
  const spatial = nx * ny * nz;
  const blocks = Math.min(nx, 24);
  const rowsPerBlock = Math.max(1, Math.ceil(nx / blocks));
  let maps = null;
  for (let rowStart = 0; rowStart < nx; rowStart += rowsPerBlock) {
    const rowEnd = Math.min(nx, rowStart + rowsPerBlock);
    const rows = rowEnd - rowStart;
    const lo = rowStart * ny * nz;
    const hi = rowEnd * ny * nz;
    const blockData = data.subarray(lo * nt, hi * nt);
    const blockMask = maskU8 ? maskU8.subarray(lo, hi) : undefined;
    const blockAux = {};
    for (const [k, v] of Object.entries(auxFlat)) blockAux[k] = v.slice(lo, hi);
    const raw = wasm.fit_volume(
      editor.text,
      blockData,
      Uint32Array.from([rows, ny, nz, nt]),
      JSON.stringify(current.meta.volume_ids),
      blockMask,
      JSON.stringify(blockAux),
      // The acquisition, when it was resolved from the data rather than written
      // in the recipe. Empty for a payload whose recipe carries the protocol.
      current.meta.protocol_json ?? "",
    );
    const blockMaps = Object.fromEntries(raw);
    if (!maps) {
      maps = {};
      for (const name of Object.keys(blockMaps)) maps[name] = new Float64Array(spatial).fill(NaN);
    }
    for (const [name, flat] of Object.entries(blockMaps)) maps[name].set(flat, lo);
    setProgress((rowEnd / nx) * 100);
    await nextFrame();
  }
  return maps ?? {};
}

async function fitSlice() {
  if (!current) { status("Pick a model first", "info"); return; }
  if (!wasm) { status("Fitting unavailable — wasm failed to load", "error"); return; }
  if (!editor.valid) {
    status("Recipe YAML is invalid — fix it before fitting", "error");
    return;
  }
  const { meta, volume, maskU8, auxFlat } = current;
  const [nx, ny, nz, nt] = meta.dims;
  status("Fitting…", "busy");
  $("fit-timing").textContent = "";
  showProgress();
  $("fit").disabled = true;
  const t0 = performance.now();
  const data = readVolumeSeries(volume, nx, ny, nz, nt);
  let maps;
  try {
    maps = await fitVolumeWithProgress(nx, ny, nz, nt, data, maskU8, auxFlat);
  } catch (e) {
    status(`Fit failed — ${e?.message ?? e}`, "error");
    hideProgress();
    $("fit").disabled = false;
    return;
  }
  lastMaps = maps;

  for (const v of [...nvOut.volumes]) nvOut.removeVolume(v);
  outputVolumes = [];
  for (const o of meta.outputs) {
    const flat = maps[o.name];
    if (!flat) continue;
    const vol = buildMapVolume(volume, flat, nx, ny, nz, o.name, o.unit, o.display_range);
    outputVolumes.push({
      name: o.name,
      unit: o.unit,
      volume: vol,
      defaultCalMin: vol.cal_min,
      defaultCalMax: vol.cal_max,
    });
  }

  const select = $("output");
  select.replaceChildren();
  for (const o of outputVolumes) {
    const opt = document.createElement("option");
    opt.value = o.name;
    opt.textContent = `${o.name}${o.unit ? ` [${o.unit}]` : ""}`;
    select.append(opt);
  }
  select.hidden = outputVolumes.length <= 1;

  // The fit itself is done; everything from here is display. A failure while
  // drawing must not leave the page reading "Fitting…" forever with its controls
  // disabled — the maps exist either way, so report the display fault and
  // release the UI.
  try {
    showOutput(outputVolumes[0]?.name);
    if (current.lastVox) plotVoxel(current.lastVox.x, current.lastVox.y, current.lastVox.z);
    // The top status line is prime real estate for every reader, but neither
    // the model summary nor "Fitted in Xs" matter there — both live beside the
    // frame-scrubbing note under the inputs viewer instead.
    status("Fitted", "ok");
  } catch (e) {
    status(`Fitted, but could not display it — ${e?.message ?? e}`, "error");
  } finally {
    $("fit-timing").textContent = `Fitted in ${((performance.now() - t0) / 1000).toFixed(1)} s`;
    hideProgress();
    $("fit").disabled = false;
    syncMapViewControls();
  }
}


// A vertical colour-scale legend beside the fitted-map viewer — NiiVue's own
// `isColorbar` only draws horizontally along the canvas's bottom edge in
// this vendored build, with no vertical/right-side placement, so this reads
// the real LUT NiiVue would have used (`nv.colormap(name)`, the same colours
// `setColormap` painted the volume with) and lays it out ourselves.
// The colour scale is drawn by the level controls themselves, which also own
// the window's handles — one widget rather than a static bar beside a slider.
function updateMapColorbar() {
  levelMain?.paint();
  levelModal?.paint();
}

function showOutput(name) {
  const entry = outputVolumes.find((o) => o.name === name);
  for (const v of [...nvOut.volumes]) nvOut.removeVolume(v);
  shownOutput = entry ?? null;
  if (!entry) return;
  nvOut.addVolume(entry.volume);
  const cmapSelect = $("colormap");
  const preferred = CMAP_BY_UNIT[entry.unit] ?? "inferno";
  const cmap = availableColormaps.includes(preferred) ? preferred : availableColormaps[0];
  if (availableColormaps.includes(cmap)) cmapSelect.value = cmap;
  nvOut.setColormap(entry.volume.id, cmapSelect.value || cmap);
  nvOut.drawScene();
  // Rebuild the histogram for whichever map is now shown — each output has its
  // own distribution, so the previous one's bins would misdescribe this window.
  levelMain?.open(entry, lastMaps?.[entry.name] ?? []);
  updateMapColorbar();
  if (current?.lastVox) updateVoxelValue(current.lastVox.x, current.lastVox.y, current.lastVox.z);
}

function onColormapChange() {
  const entry = outputVolumes.find((o) => o.name === $("output").value) ?? outputVolumes[0];
  if (!entry) return;
  nvOut.setColormap(entry.volume.id, $("colormap").value);
  nvOut.drawScene();
  updateMapColorbar();
}

// Reader-adjustable colour scale: min/max feed `volume.cal_min`/`cal_max`
// directly (the same fields NiiVue's own auto windowing sets), so the
// colorbar — which reads off the volume — tracks the change for free.
function resetCalRange() {
  if (!shownOutput) return;
  setWindow(shownOutput.defaultCalMin, shownOutput.defaultCalMax);
}

function populateColormaps() {
  const select = $("colormap");
  select.replaceChildren();
  const have = new Set(nvOut.colormaps());
  availableColormaps = CANDIDATE_COLORMAPS.filter((c) => have.has(c));
  if (availableColormaps.length === 0) availableColormaps = ["gray"];
  for (const name of availableColormaps) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    select.append(opt);
  }
}

function clearCurve() {
  curveChart?.clear();
}

// Value of the currently-displayed map at `(x, y, z)`, shown beside the
// fitted-curve parameters — updates on every crosshair move, including while
// dragging (`onLocation` calls this on every `onLocationChange`).
function updateVoxelValue(x, y, z) {
  const el = $("voxel-value");
  if (!shownOutput) {
    el.textContent = "";
    return;
  }
  const v = shownOutput.volume.getValue(x, y, z, 0);
  const unit = shownOutput.unit ? ` ${shownOutput.unit}` : "";
  el.textContent = Number.isFinite(v)
    ? `${shownOutput.name} = ${v.toPrecision(3)}${unit} at (${x}, ${y})`
    : `${shownOutput.name} = no fit at (${x}, ${y})`;
}

function plotVoxel(x, y, z) {
  if (!current) return;
  current.lastVox = { x, y, z };
  const { meta, volume, auxVolumes } = current;
  const [nx, ny, nz, nt] = meta.dims;
  $("voxel-title").textContent = `Voxel (${x}, ${y})`;
  updateVoxelValue(x, y, z);
  if (!lastMaps) {
    $("curve-note").textContent = "fit the slice first, then click a voxel";
    clearCurve();
    return;
  }
  // `lastMaps` carries every entry `fit_volume` returns — the model's full
  // `output_names()`, including diagnostics that never make it into
  // `meta.outputs` (that list is filtered to quantitative maps only, for the
  // fitted-map viewer). A curve needs the fitted *parameters*, so the real
  // question is whether the fit result has them, not whether they happen to
  // be drawable maps.
  const idx = (x * ny + y) * nz + z;
  if (!meta.params.every((p) => p in lastMaps)) {
    const missing = meta.params.filter((p) => !(p in lastMaps));
    $("curve-note").textContent =
      `this model's fit does not report ${missing.join(", ")}, so no fitted ` +
      "curve is available for it.";
    clearCurve();
    return;
  }
  const params = meta.params.map((p) => lastMaps[p][idx]);
  if (params.some((v) => !Number.isFinite(v))) {
    $("curve-note").textContent = "no fit at that voxel (outside mask or fit failed)";
    clearCurve();
    return;
  }
  const measured = [];
  for (let t = 0; t < nt; t++) measured.push(volume.getValue(x, y, 0, t));
  // forward() takes one scalar per aux name (a single voxel), unlike
  // fit_volume's flat-array-per-name contract.
  const voxelAux = {};
  for (const [auxName, auxVolume] of Object.entries(auxVolumes)) {
    voxelAux[auxName] = auxVolume.getValue(x, y, z, 0);
  }
  const predicted = JSON.parse(
    wasm.forward(
      editor.text,
      Float64Array.from(params),
      JSON.stringify(voxelAux),
      meta.protocol_json ?? "",
    ),
  );
  // A `Series` model's own measurement doesn't necessarily cover every
  // acquired volume 1:1 — e.g. mono_t2's `drop_first_echo` excludes the
  // first echo from the fit entirely, so `forward()` returns one fewer
  // sample than `nt`. Blindly zipping that shorter array against `measured`
  // by position would silently shift every later point onto the wrong
  // volume. Instead, match each returned sample back to its volume by the
  // same identity (`meta.volume_ids`) the fit itself used, leaving NaN
  // (skipped when drawing) for any volume the fit excluded. `Named` models
  // already key their measurement by role name, which is exact.
  const values = Array.isArray(predicted)
    ? alignSeriesToVolumes(predicted, meta.volume_ids)
    : meta.volume_ids.map((r) => predicted[r]);
  drawCurve(measured, values, meta.labels);
  $("curve-note").textContent = meta.params
    .map((p, k) => `${p} = ${params[k].toPrecision(3)}`)
    .join(", ");
}

// Deep-ish equality for one row of `Series` params against a `forward()`
// sample's own `params` — both are plain `{key: number}` objects, so a
// numeric-tolerant compare over the union of keys is enough.
function sameParams(a, b) {
  const keys = new Set([...Object.keys(a ?? {}), ...Object.keys(b ?? {})]);
  for (const k of keys) {
    const x = a?.[k];
    const y = b?.[k];
    if (typeof x !== "number" || typeof y !== "number") return false;
    if (Math.abs(x - y) > 1e-9 * Math.max(1, Math.abs(x), Math.abs(y))) return false;
  }
  return true;
}

function alignSeriesToVolumes(samples, volumeIds) {
  const values = new Array(volumeIds.length).fill(NaN);
  for (const sample of samples) {
    const t = volumeIds.findIndex((row) => sameParams(row, sample.params));
    if (t !== -1) values[t] = sample.value;
  }
  return values;
}

// Picks up to `max` evenly-spaced indices from `[0, n)`, always including the
// first and last — used to thin x-axis tick labels so they don't overlap
// when a series has many volumes.
function tickIndices(n, max) {
  if (n <= max) return Array.from({ length: n }, (_, k) => k);
  const idx = new Set();
  for (let i = 0; i < max; i++) idx.add(Math.round((i / (max - 1)) * (n - 1)));
  return [...idx].sort((a, b) => a - b);
}

// The single-voxel fit, as an interactive chart: measured points against the
// model's own forward curve. ECharts owns the axes, tooltip, legend and zoom, so
// none of that is hand-drawn here — and its theming is mapped onto this page's
// palette rather than shipping one of its own.
//
// `predicted[k]` may be NaN for a volume the fit excluded (mono_t2's dropped
// first echo, say); ECharts renders those as gaps, which is the honest picture.
let curveChart = null;

function ensureCurveChart() {
  const host = $("curve");
  if (!host) return null;
  if (!curveChart) {
    curveChart = echarts.init(host, null, { renderer: "canvas" });
    // The card is flex-sized, so the chart has to follow it rather than assume
    // the size it was created at.
    new ResizeObserver(() => curveChart.resize()).observe(host);
  }
  return curveChart;
}

function drawCurve(measured, predicted, labels = []) {
  const chart = ensureCurveChart();
  if (!chart) return;
  const style = getComputedStyle(document.documentElement);
  const ink = style.getPropertyValue("--ink").trim();
  const muted = style.getPropertyValue("--muted").trim();
  const line = style.getPropertyValue("--line").trim();
  const accent = style.getPropertyValue("--accent").trim();
  const rust = style.getPropertyValue("--rust").trim();
  const panel = style.getPropertyValue("--panel").trim();

  chart.setOption(
    {
      animation: false,
      grid: { left: 56, right: 16, top: 28, bottom: 40, containLabel: false },
      legend: {
        data: ["measured", "fitted"],
        top: 0,
        textStyle: { color: muted, fontSize: 11 },
        inactiveColor: line,
      },
      tooltip: {
        trigger: "axis",
        backgroundColor: panel,
        borderColor: line,
        textStyle: { color: ink, fontSize: 11 },
        // The x label is the volume's own identity (e.g. "InversionTime=0.65"),
        // so a reader sees which acquisition a point belongs to.
        axisPointer: { type: "cross", label: { backgroundColor: muted } },
      },
      xAxis: {
        type: "category",
        data: labels.length ? labels : measured.map((_, k) => String(k + 1)),
        axisLine: { lineStyle: { color: line } },
        axisLabel: { color: muted, fontSize: 10, hideOverlap: true },
        axisTick: { lineStyle: { color: line } },
      },
      yAxis: {
        type: "value",
        scale: true,
        name: "signal",
        nameTextStyle: { color: muted, fontSize: 10, align: "right" },
        axisLine: { lineStyle: { color: line } },
        axisLabel: { color: muted, fontSize: 10 },
        splitLine: { lineStyle: { color: line, opacity: 0.45 } },
      },
      // Drag to zoom into a subset of the acquisition axis; useful for a
      // 30-echo series where the interesting part is the first few.
      dataZoom: [
        { type: "inside", zoomOnMouseWheel: "shift", moveOnMouseWheel: false },
      ],
      series: [
        {
          name: "measured",
          type: "scatter",
          symbolSize: 7,
          itemStyle: { color: accent },
          data: measured.map((v) => (Number.isFinite(v) ? v : null)),
        },
        {
          name: "fitted",
          type: "line",
          smooth: false,
          showSymbol: false,
          connectNulls: false,
          lineStyle: { color: rust, width: 2 },
          itemStyle: { color: rust },
          data: predicted.map((v) => (Number.isFinite(v) ? v : null)),
        },
      ],
    },
    { notMerge: true },
  );
}

function onMapHover(event) {
  if (!shownOutput || !current) return;
  const nv = event.currentTarget === nvModal?.canvas ? nvModal : nvOut;
  // `canvasPos2frac` works in the canvas's backing-store pixels, which differ
  // from CSS pixels whenever the canvas is high-resolution. Deriving the ratio
  // from the canvas itself is right whatever the display's density.
  const rect = nv.canvas.getBoundingClientRect();
  if (!rect.width || !rect.height) return;
  const sx = nv.canvas.width / rect.width;
  const sy = nv.canvas.height / rect.height;
  const frac = nv.canvasPos2frac([
    (event.clientX - rect.left) * sx,
    (event.clientY - rect.top) * sy,
  ]);
  // `canvasPos2frac` reports a negative first component when the cursor is not
  // over a slice at all (the gaps in a multiplanar view, say).
  if (!frac || frac[0] < 0) {
    levelMain?.mark(null);
    levelModal?.mark(null);
    return;
  }
  const [x, y, z] = nv.frac2vox(frac);
  const v = shownOutput.volume.getValue(x, y, z, 0);
  levelMain?.mark(Number.isFinite(v) ? v : null);
  levelModal?.mark(Number.isFinite(v) ? v : null);
}

function clearMapHover() {
  levelMain?.mark(null);
  levelModal?.mark(null);
}

function onLocation(loc) {
  if (!current || !loc?.vox) return;
  const [x, y, z] = loc.vox.map((v) => Math.round(v));
  const [nx, ny, nz] = current.meta.dims;
  if (x < 0 || y < 0 || z < 0 || x >= nx || y >= ny || z >= nz) return;
  plotVoxel(x, y, z);
  // Mark the crosshair's own value too. These voxel indices are NiiVue's, so
  // this path needs no coordinate conversion of ours.
  if (shownOutput) {
    const v = shownOutput.volume.getValue(x, y, z, 0);
    levelMain?.mark(Number.isFinite(v) ? v : null);
    levelModal?.mark(Number.isFinite(v) ? v : null);
  }
}

async function main() {
  await nvIn.attachTo("gl-in");
  await nvOut.attachTo("gl-out");
  // Otherwise the canvas backing store renders at 1x and is upscaled by CSS
  // to its layout size — soft/blurry on any HiDPI (retina) display,
  // regardless of how much native resolution the bundle ships. NiiVue's own
  // `resizeListener` (already called on every model load and viewer resize)
  // keeps the backing store matched to `devicePixelRatio` once this is set.
  nvIn.setHighResolutionCapable(true);
  nvOut.setHighResolutionCapable(true);
  populateColormaps();

  // Synced crosshairs both ways, so dragging in either viewer moves the
  // other; click handling is registered on both instances too, so a click
  // on the fitted map updates the voxel curve exactly as one on the inputs
  // viewer does.
  nvIn.broadcastTo([nvOut], { "2d": true, "3d": true });
  nvOut.broadcastTo([nvIn], { "2d": true, "3d": true });
  nvIn.onLocationChange = onLocation;
  nvOut.onLocationChange = onLocation;
  // NiiVue steps a volume's 4D frame on its own (ArrowLeft/ArrowRight, bound
  // internally to `frame_previous`/`frame_next`) whenever the inputs viewer
  // has focus — every path ends up at `setFrame4D`, which fires this
  // callback, so the slider/label stay in sync with the arrow keys exactly
  // as they already do with the wheel and the slider itself.
  nvIn.onFrameChange = (volume, frame) => {
    if (!current || volume.id !== current.volume.id) return;
    current.frame = frame;
    $("frame").value = String(frame);
    $("frame-label").textContent = current.meta.labels[frame] ?? "";
    syncFilesHighlight();
  };

  wasm = await loadWasm();

  let index;
  try {
    index = await (await fetchOrThrow("./data/index.json")).json();
  } catch (e) {
    status(`Could not load the model index — ${e.message}`, "error");
    return;
  }

  modelNames = index.models;
  const select = $("model");
  for (const name of index.models) {
    let meta;
    try {
      meta = await loadBundle(name);
    } catch (e) {
      status(`Could not load ${name} — ${e.message}`, "error");
      continue;
    }
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = meta.title;
    select.append(opt);
  }

  select.onchange = () => loadModel(select.value);
  $("frame").oninput = onFrameChange;
  $("fit").onclick = fitSlice;
  $("output").onchange = (e) => showOutput(e.target.value);
  $("colormap").onchange = onColormapChange;
  $("tab-form").onclick = () => showTab("form");
  $("tab-yaml").onclick = () => showTab("yaml");
  $("tab-viewer").onclick = () => showInputsTab("viewer");
  $("tab-files").onclick = () => showInputsTab("files");
  $("tab-slice").onclick = () => showMapView("slice");
  $("tab-planes").onclick = () => showMapView("planes");
  $("open-map-modal").onclick = openMapModal;
  $("cfg-yaml").addEventListener("scroll", syncYamlScroll);

  // Bring-your-own-data panel. `dragover` must be prevented for a drop to fire
  // at all; `dragleave` is filtered to the panel itself, since it also fires
  // when the cursor crosses onto a child.
  const dropZone = $("drop-wrap");
  dropZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    dropZone.classList.add("drop-over");
  });
  dropZone.addEventListener("dragleave", (e) => {
    if (e.target === dropZone) dropZone.classList.remove("drop-over");
  });
  dropZone.addEventListener("drop", onDrop);
  $("browse-folder").onclick = () => $("folder-input").click();
  $("browse-zip").onclick = () => $("zip-input").click();
  for (const id of ["folder-input", "zip-input"]) {
    $(id).addEventListener("change", (e) => {
      if (e.target.files.length) onBrowse(e.target.files);
      // Reset, so picking the same folder twice fires `change` again.
      e.target.value = "";
    });
  }
  $("files-tree").addEventListener("click", onFilesClick);
  $("file-modal-close").onclick = closeFileModal;
  levelMain = createLevelControl("mlevel");
  $("file-modal").addEventListener("click", (e) => {
    if (e.target === $("file-modal")) closeFileModal();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !$("file-modal").hidden) closeFileModal();
  });
  $("cfg-yaml").oninput = (e) => setEditorText(e.target.value);
  $("cal-reset").onclick = resetCalRange;
  $("roi-toggle").onclick = toggleRoi;
  $("roi-clear").onclick = clearRoi;
  // Recompute after each stroke, so the numbers track the region as it is drawn.
  nvOut.onDrawingChanged = renderRoiStats;
  nvOut.canvas.addEventListener("mousemove", onMapHover);
  nvOut.canvas.addEventListener("mouseleave", clearMapHover);

  // Wheel-to-scrub, alongside the existing slider: a reader hovering the
  // inputs viewer steps through frames without reaching for the slider,
  // useful once a model ships several volumes. Captured (not bubble-phase)
  // and stopped here, ahead of NiiVue's own wheel-to-zoom handler on the
  // canvas — this viewer's wheel gesture means "step frames", not "zoom the
  // slice" (the vendored build's own wheel handling is for slice zoom/scroll
  // and click-to-segment, not 4D frame stepping, so there is no built-in
  // gesture to opt into for this instead).
  //
  // A single mouse-wheel notch and a single trackpad two-finger gesture both
  // arrive as a *stream* of wheel events (a trackpad especially fires many
  // small ones), so stepping on every event blows through several frames per
  // gesture. Accumulate `deltaY` and only step once it crosses a threshold —
  // tuned to the ~100-120 one Chrome/Firefox mouse-wheel notch reports, and
  // large enough that one full trackpad swipe is one frame, not several.
  $("viewer-in").addEventListener(
    "wheel",
    (e) => {
      if (!current) return;
      const [, , , nt] = current.meta.dims;
      if (nt <= 1) return;
      e.preventDefault();
      e.stopPropagation();
      wheelAccum += e.deltaY;
      if (Math.abs(wheelAccum) < WHEEL_STEP_THRESHOLD) return;
      const dir = wheelAccum > 0 ? 1 : -1;
      wheelAccum = 0;
      const id = current.volume.id;
      const t = Math.min(nt - 1, Math.max(0, nvIn.getFrame4D(id) + dir));
      if (t === nvIn.getFrame4D(id)) return;
      goToFrame(t);
    },
    { passive: false, capture: true },
  );

  if (select.options.length) {
    await loadModel(select.value);
  }
}

main();

// Read-only state accessor for automated smoke-testing; no UI depends on this.
window.__playground = { maps: () => lastMaps, editor: () => editor };
